export const GAME_COUNT = GAMES.length;

/** Games surfaced in the "Featured" carousel, chosen to span every category. */
export const FEATURED_IDS = [
  'star_lancer', 'circuit_chase', 'gem_cascade', 'letter_lock',
  'mini_sudoku', 'reflex_meter', 'code_break', 'neon_serpent',
  'fusion_grid', 'pair_hunt', 'add_sprint', 'maze_escape',
] as const;

export const FEATURED_GAMES: Game[] = FEATURED_IDS
  .map((id) => GAMES.find((g) => g.id === id))
  .filter((g): g is Game => Boolean(g));

export function gamesByCategory(category: CategoryId): Game[] {
  return GAMES.filter((g) => g.category === category);
}
